@page "/recipes/category/{CategoryName}"
@using RecipeCommunity.Services
@using RecipeCommunity.Models

<PageTitle>@CategoryName Recipes - Recipe Community</PageTitle>

<div class="container mt-4">
    <nav aria-label="breadcrumb">
        <ol class="breadcrumb">
            <li class="breadcrumb-item"><a href="/">Home</a></li>
            <li class="breadcrumb-item active">@CategoryName</li>
        </ol>
    </nav>

    <h1 class="mb-4">@CategoryName Recipes</h1>

    @if (Recipes.Count == 0)
    {
        <div class="alert alert-info">No recipes found in this category yet. Be the first to submit one!</div>
    }
    else
    {
        <div class="row">
            @foreach (var recipe in Recipes)
            {
                <div class="col-md-6 mb-4">
                    <div class="card h-100 shadow-sm">
                        <div class="card-body">
                            <h5 class="card-title">@recipe.Title</h5>
                            <p class="card-text text-muted">
                                ⭐ @recipe.AverageRating / 5 (@recipe.RatingCount ratings)
                            </p>
                            <a href="/recipes/@recipe.Id" class="btn btn-primary">View Recipe</a>
                        </div>
                    </div>
                </div>
            }
        </div>
    }
</div>

@code {
    [Parameter] public string CategoryName { get; set; } = string.Empty;
    [Inject] public RecipeService RecipeService { get; set; } = default!;

    private List<Recipe> Recipes { get; set; } = new();

    protected override void OnParametersSet()
    {
        Recipes = RecipeService.GetRecipesByCategory(CategoryName);
    }
}

@page "/recipes/{Id:int}"
@using RecipeCommunity.Services
@using RecipeCommunity.Models

<PageTitle>@(Recipe?.Title ?? "Recipe") - Recipe Community</PageTitle>

<div class="container mt-4">
    <nav aria-label="breadcrumb">
        <ol class="breadcrumb">
            <li class="breadcrumb-item"><a href="/">Home</a></li>
            @if (Recipe is not null)
            {
                <li class="breadcrumb-item"><a href="/recipes/category/@Recipe.Category">@Recipe.Category</a></li>
                <li class="breadcrumb-item active">@Recipe.Title</li>
            }
        </ol>
    </nav>

    @if (Recipe is null)
    {
        <div class="alert alert-warning">Recipe not found.</div>
    }
    else
    {
        <div class="card shadow-sm">
            <div class="card-body">
                <h1 class="card-title">@Recipe.Title</h1>
                <span class="badge bg-secondary mb-3">@Recipe.Category</span>

                <h4 class="mt-4">📋 Ingredients</h4>
                <ul class="list-group list-group-flush mb-4">
                    @foreach (var ingredient in Recipe.Ingredients.Split('\n', StringSplitOptions.RemoveEmptyEntries))
                    {
                        <li class="list-group-item">@ingredient</li>
                    }
                </ul>

                <h4>👨‍🍳 Steps</h4>
                <div class="mb-4">
                    @foreach (var step in Recipe.Steps.Split('\n', StringSplitOptions.RemoveEmptyEntries))
                    {
                        <p>@step</p>
                    }
                </div>

                <hr />
                <h4>⭐ Rating</h4>
                <p class="text-muted">Average: @Recipe.AverageRating / 5 (@Recipe.RatingCount ratings)</p>

                <RecipeCommunity.Components.Shared.StarRating RecipeId="Recipe.Id" />
            </div>
        </div>
    }
</div>

@code {
    [Parameter] public int Id { get; set; }
    [Inject] public RecipeService RecipeService { get; set; } = default!;

    private Recipe? Recipe { get; set; }

    protected override void OnParametersSet()
    {
        Recipe = RecipeService.GetRecipeById(Id);
    }
}

@rendermode InteractiveServer
@using RecipeCommunity.Services

<div class="d-inline-block">
    @for (int i = 1; i <= 5; i++)
    {
        var star = i;
        <span class="fs-3" role="button" style="cursor: pointer; color: @(star <= SelectedRating ? "gold" : "#ccc")"
              @onclick="() => Rate(star)">
            ★
        </span>
    }

    @if (Submitted)
    {
        <span class="ms-2 text-success fw-bold">Thanks for rating!</span>
    }
</div>

@code {
    [Parameter] public int RecipeId { get; set; }
    [Inject] public RecipeService RecipeService { get; set; } = default!;

    private int SelectedRating { get; set; }
    private bool Submitted { get; set; }

    private void Rate(int stars)
    {
        SelectedRating = stars;
        RecipeService.AddRating(RecipeId, stars);
        Submitted = true;
    }
}

@page "/recipes/submit"
@rendermode InteractiveServer
@using RecipeCommunity.Services
@using RecipeCommunity.Models

<PageTitle>Submit a Recipe - Recipe Community</PageTitle>

<div class="container mt-4">
    <nav aria-label="breadcrumb">
        <ol class="breadcrumb">
            <li class="breadcrumb-item"><a href="/">Home</a></li>
            <li class="breadcrumb-item active">Submit Recipe</li>
        </ol>
    </nav>

    <h1 class="mb-4">📝 Submit Your Recipe</h1>

    @if (SubmitSuccess)
    {
        <div class="alert alert-success">
            <h4>Recipe submitted successfully!</h4>
            <p>Your recipe "<strong>@NewRecipe.Title</strong>" has been added to the community.</p>
            <a href="/recipes/category/@NewRecipe.Category" class="btn btn-primary">View Category</a>
            <button class="btn btn-outline-secondary ms-2" @onclick="ResetForm">Submit Another</button>
        </div>
    }
    else
    {
        <div class="card shadow-sm">
            <div class="card-body">
                <EditForm Model="NewRecipe" OnValidSubmit="HandleSubmit" FormName="submitRecipe">
                    <DataAnnotationsValidator />
                    <ValidationSummary class="text-danger" />

                    <div class="mb-3">
                        <label for="title" class="form-label">Recipe Title</label>
                        <InputText id="title" class="form-control" @bind-Value="NewRecipe.Title"
                                   placeholder="e.g., Grandma's Apple Pie" />
                    </div>

                    <div class="mb-3">
                        <label for="category" class="form-label">Category</label>
                        <InputSelect id="category" class="form-select" @bind-Value="NewRecipe.Category">
                            <option value="">-- Select a category --</option>
                            @foreach (var cat in RecipeService.GetCategories())
                            {
                                <option value="@cat.Name">@cat.Name</option>
                            }
                        </InputSelect>
                    </div>

                    <div class="mb-3">
                        <label for="ingredients" class="form-label">Ingredients (one per line)</label>
                        <InputTextArea id="ingredients" class="form-control" rows="6"
                                       @bind-Value="NewRecipe.Ingredients"
                                       placeholder="2 cups flour&#10;1 cup sugar&#10;3 eggs" />
                    </div>

                    <div class="mb-3">
                        <label for="steps" class="form-label">Steps (one per line)</label>
                        <InputTextArea id="steps" class="form-control" rows="6"
                                       @bind-Value="NewRecipe.Steps"
                                       placeholder="1. Preheat oven to 350°F.&#10;2. Mix dry ingredients.&#10;3. Add wet ingredients." />
                    </div>

                    <button type="submit" class="btn btn-success btn-lg"
                            disabled="@(!IsFormValid)">
                        Submit Recipe
                    </button>
                </EditForm>
            </div>
        </div>
    }
</div>

@code {
    [Inject] public RecipeService RecipeService { get; set; } = default!;

    private Recipe NewRecipe { get; set; } = new();
    private bool SubmitSuccess { get; set; }

    private bool IsFormValid =>
        !string.IsNullOrWhiteSpace(NewRecipe.Title) &&
        !string.IsNullOrWhiteSpace(NewRecipe.Category) &&
        !string.IsNullOrWhiteSpace(NewRecipe.Ingredients) &&
        !string.IsNullOrWhiteSpace(NewRecipe.Steps);

    private void HandleSubmit()
    {
        if (!IsFormValid) return;
        RecipeService.AddRecipe(NewRecipe);
        SubmitSuccess = true;
    }

    private void ResetForm()
    {
        NewRecipe = new Recipe();
        SubmitSuccess = false;
    }
}

